INSERT INTO `pages` VALUES (1,'Homepage','<div>[featured-posts limit=\"5\" enable_lazy_loading=\"yes\"][/featured-posts]</div><div>[simple-slider key=\"home-slider\" enable_lazy_loading=\"yes\"][/simple-slider]</div><div>[category-posts enable_lazy_loading=\"yes\"][/category-posts]</div><div>[all-galleries enable_lazy_loading=\"yes\"][/all-galleries]</div>','published',1,NULL,'homepage',NULL,'2026-03-06 01:34:15','2026-03-06 01:34:15'),(2,'Introduction','<p>Welcome to our platform, where we bring you the latest news, insights, and stories from around the world. Our mission is to provide high-quality content that informs, inspires, and engages our readers. We are committed to journalistic excellence and integrity in everything we do.</p><p>Founded by a team of experienced journalists and content creators, we have built a reputation for delivering accurate, balanced, and thought-provoking articles across a wide range of topics including technology, business, lifestyle, culture, and more.</p><p>Our editorial team works tirelessly to ensure that every piece of content meets our high standards. We believe in the power of storytelling to make a difference in people\'s lives and to help them better understand the world around them.</p><p>Thank you for being part of our community. We look forward to continuing to serve you with the best content possible.</p>','published',1,NULL,NULL,NULL,'2026-03-06 01:34:15','2026-03-06 01:34:15'),(3,'About us','<p>We are a leading digital media company dedicated to delivering exceptional content to our readers worldwide. With a team of talented writers, editors, and content creators, we cover the stories that matter most to you.</p><p>Our platform features in-depth analysis, breaking news, expert opinions, and engaging multimedia content. We pride ourselves on our commitment to accuracy, fairness, and transparency in our reporting.</p><p>What sets us apart is our focus on quality over quantity. Every article is carefully researched, fact-checked, and edited to ensure we deliver the most reliable information to our audience. We believe that informed readers make better decisions, and we strive to be your trusted source of information.</p><p>Join us on our journey as we continue to grow and evolve. We are always looking for ways to improve and better serve our community. Your feedback and support are what drive us to be better every day.</p>','published',1,NULL,NULL,NULL,'2026-03-06 01:34:15','2026-03-06 01:34:15'),(4,'Contact','<p>123 Main Street, Downtown District, Metro City, ST 12345</p><p>+1 (555) 123-4567 (4 lines) - +1 (555) 987-6543</p><p>+1 (555) 246-8135</p><p>contact@example.com&nbsp;&nbsp;</p><div>[contact-form][/contact-form]</div>','published',1,NULL,NULL,NULL,'2026-03-06 01:34:15','2026-03-06 01:34:15'),(5,'Cookie Policy','<h3>EU Cookie Consent</h3><p>To use this website we are using Cookies and collecting some Data. To be compliant with the EU GDPR we give you to choose if you allow us to use certain Cookies and to collect some Data.</p><h4>Essential Data</h4><p>The Essential Data is needed to run the Site you are visiting technically. You can not deactivate them.</p><p>- Session Cookie: PHP uses a Cookie to identify user sessions. Without this Cookie the Website is not working.</p><p>- XSRF-Token Cookie: Laravel automatically generates a CSRF \"token\" for each active user session managed by the application. This token is used to verify that the authenticated user is the one actually making the requests to the application.</p>','published',1,NULL,NULL,NULL,'2026-03-06 01:34:15','2026-03-06 01:34:15');
/*!40000 ALTER TABLE `pages` ENABLE KEYS */;
UNLOCK TABLES;

