INSERT INTO `pages_translations` VALUES ('ar',1,'الرئيسية',NULL,'<div>[featured-posts limit=\"5\" enable_lazy_loading=\"yes\"][/featured-posts]</div><div>[simple-slider key=\"home-slider\" enable_lazy_loading=\"yes\"][/simple-slider]</div><div>[category-posts enable_lazy_loading=\"yes\"][/category-posts]</div><div>[all-galleries enable_lazy_loading=\"yes\"][/all-galleries]</div>'),('ar',2,'مقدمة',NULL,'<p>مرحبًا بكم في منصتنا، حيث نقدم لكم أحدث الأخبار والرؤى والقصص من جميع أنحاء العالم. مهمتنا هي تقديم محتوى عالي الجودة يُعلم ويُلهم ويُشرك قرائنا. نحن ملتزمون بالتميز الصحفي والنزاهة في كل ما نقوم به.</p><p>تأسست على يد فريق من الصحفيين وصناع المحتوى ذوي الخبرة، وقد بنينا سمعة في تقديم مقالات دقيقة ومتوازنة ومحفزة للتفكير عبر مجموعة واسعة من المواضيع بما في ذلك التكنولوجيا والأعمال ونمط الحياة والثقافة والمزيد.</p><p>يعمل فريق التحرير لدينا بلا كلل لضمان أن كل قطعة محتوى تلبي معاييرنا العالية. نؤمن بقوة السرد القصصي في إحداث فرق في حياة الناس ومساعدتهم على فهم العالم من حولهم بشكل أفضل.</p><p>شكرًا لكونكم جزءًا من مجتمعنا. نتطلع إلى الاستمرار في خدمتكم بأفضل محتوى ممكن.</p>'),('ar',3,'من نحن',NULL,'<p>نحن شركة إعلامية رقمية رائدة مكرسة لتقديم محتوى استثنائي لقرائنا في جميع أنحاء العالم. مع فريق من الكتاب والمحررين وصناع المحتوى الموهوبين، نغطي القصص الأهم بالنسبة لكم.</p><p>تتميز منصتنا بالتحليل المعمق والأخبار العاجلة وآراء الخبراء والمحتوى المتعدد الوسائط الجذاب. نفتخر بالتزامنا بالدقة والإنصاف والشفافية في تقاريرنا.</p><p>ما يميزنا هو تركيزنا على الجودة بدلاً من الكمية. كل مقال يتم بحثه بعناية والتحقق من صحته وتحريره لضمان تقديم أكثر المعلومات موثوقية لجمهورنا. نؤمن بأن القراء المطلعين يتخذون قرارات أفضل، ونسعى لنكون مصدركم الموثوق للمعلومات.</p><p>انضموا إلينا في رحلتنا بينما نستمر في النمو والتطور. نبحث دائمًا عن طرق للتحسين وخدمة مجتمعنا بشكل أفضل. ملاحظاتكم ودعمكم هي ما يدفعنا لنكون أفضل كل يوم.</p>'),('ar',4,'اتصل بنا',NULL,'<p>123 الشارع الرئيسي، حي وسط المدينة، مدينة مترو، ST 12345</p><p>+1 (555) 123-4567 (4 خطوط) - +1 (555) 987-6543</p><p>+1 (555) 246-8135</p><p>contact@example.com&nbsp;&nbsp;</p><div>[contact-form][/contact-form]</div>'),('ar',5,'Cookie Policy',NULL,'<h3>EU Cookie Consent</h3><p>To use this website we are using Cookies and collecting some Data. To be compliant with the EU GDPR we give you to choose if you allow us to use certain Cookies and to collect some Data.</p><h4>Essential Data</h4><p>The Essential Data is needed to run the Site you are visiting technically. You can not deactivate them.</p><p>- Session Cookie: PHP uses a Cookie to identify user sessions. Without this Cookie the Website is not working.</p><p>- XSRF-Token Cookie: Laravel automatically generates a CSRF \"token\" for each active user session managed by the application. This token is used to verify that the authenticated user is the one actually making the requests to the application.</p>'),('fr',1,'Accueil',NULL,'<div>[featured-posts limit=\"5\" enable_lazy_loading=\"yes\"][/featured-posts]</div><div>[simple-slider key=\"home-slider\" enable_lazy_loading=\"yes\"][/simple-slider]</div><div>[category-posts enable_lazy_loading=\"yes\"][/category-posts]</div><div>[all-galleries enable_lazy_loading=\"yes\"][/all-galleries]</div>'),('fr',2,'Introduction',NULL,'<p>Bienvenue sur notre plateforme, où nous vous apportons les dernières nouvelles, analyses et histoires du monde entier. Notre mission est de fournir un contenu de haute qualité qui informe, inspire et engage nos lecteurs. Nous sommes engagés dans l\'excellence journalistique et l\'intégrité dans tout ce que nous faisons.</p><p>Fondée par une équipe de journalistes et créateurs de contenu expérimentés, nous avons bâti une réputation de livraison d\'articles précis, équilibrés et stimulants sur un large éventail de sujets incluant la technologie, les affaires, le style de vie, la culture et plus encore.</p><p>Notre équipe éditoriale travaille sans relâche pour s\'assurer que chaque contenu répond à nos standards élevés. Nous croyons au pouvoir de la narration pour faire la différence dans la vie des gens et les aider à mieux comprendre le monde qui les entoure.</p><p>Merci de faire partie de notre communauté. Nous avons hâte de continuer à vous servir avec le meilleur contenu possible.</p>'),('fr',3,'À propos',NULL,'<p>Nous sommes une entreprise de médias numériques de premier plan, dédiée à fournir un contenu exceptionnel à nos lecteurs dans le monde entier. Avec une équipe de rédacteurs, éditeurs et créateurs de contenu talentueux, nous couvrons les histoires qui comptent le plus pour vous.</p><p>Notre plateforme propose des analyses approfondies, des nouvelles de dernière heure, des opinions d\'experts et un contenu multimédia engageant. Nous sommes fiers de notre engagement envers la précision, l\'équité et la transparence dans nos reportages.</p><p>Ce qui nous distingue est notre concentration sur la qualité plutôt que la quantité. Chaque article est soigneusement recherché, vérifié et édité pour garantir que nous fournissons les informations les plus fiables à notre public. Nous croyons que des lecteurs informés prennent de meilleures décisions, et nous nous efforçons d\'être votre source d\'information de confiance.</p><p>Rejoignez-nous dans notre voyage alors que nous continuons à grandir et évoluer. Nous cherchons toujours des moyens de nous améliorer et de mieux servir notre communauté. Vos retours et votre soutien sont ce qui nous pousse à être meilleurs chaque jour.</p>'),('fr',4,'Contact',NULL,'<p>123 Rue Principale, Quartier Centre-Ville, Métro City, ST 12345</p><p>+1 (555) 123-4567 (4 lignes) - +1 (555) 987-6543</p><p>+1 (555) 246-8135</p><p>contact@example.com&nbsp;&nbsp;</p><div>[contact-form][/contact-form]</div>'),('fr',5,'Cookie Policy',NULL,'<h3>EU Cookie Consent</h3><p>To use this website we are using Cookies and collecting some Data. To be compliant with the EU GDPR we give you to choose if you allow us to use certain Cookies and to collect some Data.</p><h4>Essential Data</h4><p>The Essential Data is needed to run the Site you are visiting technically. You can not deactivate them.</p><p>- Session Cookie: PHP uses a Cookie to identify user sessions. Without this Cookie the Website is not working.</p><p>- XSRF-Token Cookie: Laravel automatically generates a CSRF \"token\" for each active user session managed by the application. This token is used to verify that the authenticated user is the one actually making the requests to the application.</p>'),('id',1,'Beranda',NULL,'<div>[featured-posts limit=\"5\" enable_lazy_loading=\"yes\"][/featured-posts]</div><div>[simple-slider key=\"home-slider\" enable_lazy_loading=\"yes\"][/simple-slider]</div><div>[category-posts enable_lazy_loading=\"yes\"][/category-posts]</div><div>[all-galleries enable_lazy_loading=\"yes\"][/all-galleries]</div>'),('id',2,'Pengantar',NULL,'<p>Selamat datang di platform kami, di mana kami menghadirkan berita terbaru, wawasan, dan cerita dari seluruh dunia. Misi kami adalah menyediakan konten berkualitas tinggi yang menginformasikan, menginspirasi, dan melibatkan pembaca kami. Kami berkomitmen pada keunggulan jurnalistik dan integritas dalam segala hal yang kami lakukan.</p><p>Didirikan oleh tim jurnalis dan pembuat konten berpengalaman, kami telah membangun reputasi dalam memberikan artikel yang akurat, seimbang, dan menggugah pikiran di berbagai topik termasuk teknologi, bisnis, gaya hidup, budaya, dan lainnya.</p><p>Tim editorial kami bekerja tanpa lelah untuk memastikan setiap konten memenuhi standar tinggi kami. Kami percaya pada kekuatan bercerita untuk membuat perbedaan dalam kehidupan orang dan membantu mereka memahami dunia di sekitar mereka dengan lebih baik.</p><p>Terima kasih telah menjadi bagian dari komunitas kami. Kami berharap dapat terus melayani Anda dengan konten terbaik yang mungkin.</p>'),('id',3,'Tentang Kami',NULL,'<p>Kami adalah perusahaan media digital terkemuka yang berdedikasi untuk memberikan konten luar biasa kepada pembaca kami di seluruh dunia. Dengan tim penulis, editor, dan pembuat konten berbakat, kami meliput cerita yang paling penting bagi Anda.</p><p>Platform kami menampilkan analisis mendalam, berita terkini, pendapat ahli, dan konten multimedia yang menarik. Kami bangga dengan komitmen kami terhadap akurasi, keadilan, dan transparansi dalam pelaporan kami.</p><p>Yang membedakan kami adalah fokus kami pada kualitas daripada kuantitas. Setiap artikel diteliti dengan cermat, diperiksa faktanya, dan diedit untuk memastikan kami memberikan informasi paling andal kepada audiens kami. Kami percaya bahwa pembaca yang terinformasi membuat keputusan yang lebih baik, dan kami berusaha menjadi sumber informasi terpercaya Anda.</p><p>Bergabunglah dengan kami dalam perjalanan kami saat kami terus tumbuh dan berkembang. Kami selalu mencari cara untuk meningkatkan dan melayani komunitas kami dengan lebih baik. Umpan balik dan dukungan Anda adalah yang mendorong kami menjadi lebih baik setiap hari.</p>'),('id',4,'Kontak',NULL,'<p>123 Jalan Utama, Distrik Pusat Kota, Kota Metro, ST 12345</p><p>+1 (555) 123-4567 (4 saluran) - +1 (555) 987-6543</p><p>+1 (555) 246-8135</p><p>contact@example.com&nbsp;&nbsp;</p><div>[contact-form][/contact-form]</div>'),('id',5,'Cookie Policy',NULL,'<h3>EU Cookie Consent</h3><p>To use this website we are using Cookies and collecting some Data. To be compliant with the EU GDPR we give you to choose if you allow us to use certain Cookies and to collect some Data.</p><h4>Essential Data</h4><p>The Essential Data is needed to run the Site you are visiting technically. You can not deactivate them.</p><p>- Session Cookie: PHP uses a Cookie to identify user sessions. Without this Cookie the Website is not working.</p><p>- XSRF-Token Cookie: Laravel automatically generates a CSRF \"token\" for each active user session managed by the application. This token is used to verify that the authenticated user is the one actually making the requests to the application.</p>'),('tr',1,'Ana Sayfa',NULL,'<div>[featured-posts limit=\"5\" enable_lazy_loading=\"yes\"][/featured-posts]</div><div>[simple-slider key=\"home-slider\" enable_lazy_loading=\"yes\"][/simple-slider]</div><div>[category-posts enable_lazy_loading=\"yes\"][/category-posts]</div><div>[all-galleries enable_lazy_loading=\"yes\"][/all-galleries]</div>'),('tr',2,'Tanıtım',NULL,'<p>Dünya genelinden en son haberleri, görüşleri ve hikayeleri sizlere sunduğumuz platformumuza hoş geldiniz. Misyonumuz, okuyucularımızı bilgilendiren, ilham veren ve etkileşen yüksek kaliteli içerik sunmaktır. Yaptığımız her şeyde gazetecilik mükemmelliğine ve dürüstlüğe bağlıyız.</p><p>Deneyimli gazeteciler ve içerik üreticilerinden oluşan bir ekip tarafından kurulan şirketimiz, teknoloji, iş, yaşam tarzı, kültür ve daha fazlasını kapsayan geniş bir yelpazede doğru, dengeli ve düşündürücü makaleler sunma konusunda bir itibar oluşturmuştur.</p><p>Editöryal ekibimiz, her içeriğin yüksek standartlarımızı karşılamasını sağlamak için yorulmadan çalışır. Hikaye anlatımının insanların hayatlarında fark yaratma ve çevrelerindeki dünyayı daha iyi anlamalarına yardımcı olma gücüne inanıyoruz.</p><p>Topluluğumuzun bir parçası olduğunuz için teşekkür ederiz. Size mümkün olan en iyi içerikle hizmet vermeye devam etmeyi dört gözle bekliyoruz.</p>'),('tr',3,'Hakkımızda',NULL,'<p>Dünya genelindeki okuyucularımıza olağanüstü içerik sunmaya adanmış öncü bir dijital medya şirketiyiz. Yetenekli yazarlar, editörler ve içerik üreticilerinden oluşan ekibimizle, sizin için en önemli haberleri sunuyoruz.</p><p>Platformumuz derinlemesine analizler, son dakika haberleri, uzman görüşleri ve ilgi çekici multimedya içerikleri sunar. Raporlarımızda doğruluk, adalet ve şeffaflık taahhüdümüzle gurur duyuyoruz.</p><p>Bizi farklı kılan, nicelik yerine kaliteye odaklanmamızdır. Her makale, izleyicilerimize en güvenilir bilgileri sunmamızı sağlamak için dikkatle araştırılır, doğrulanır ve düzenlenir. Bilgilendirilmiş okuyucuların daha iyi kararlar verdiğine inanıyoruz ve güvenilir bilgi kaynağınız olmaya çalışıyoruz.</p><p>Büyümeye ve gelişmeye devam ederken yolculuğumuza katılın. Her zaman geliştirmenin ve topluluğumuza daha iyi hizmet etmenin yollarını arıyoruz. Geri bildirimleriniz ve desteğiniz bizi her gün daha iyi olmaya yönlendiren şeydir.</p>'),('tr',4,'İletişim',NULL,'<p>123 Ana Cadde, Şehir Merkezi, Metro Şehir, ST 12345</p><p>+1 (555) 123-4567 (4 hat) - +1 (555) 987-6543</p><p>+1 (555) 246-8135</p><p>contact@example.com&nbsp;&nbsp;</p><div>[contact-form][/contact-form]</div>'),('tr',5,'Cookie Policy',NULL,'<h3>EU Cookie Consent</h3><p>To use this website we are using Cookies and collecting some Data. To be compliant with the EU GDPR we give you to choose if you allow us to use certain Cookies and to collect some Data.</p><h4>Essential Data</h4><p>The Essential Data is needed to run the Site you are visiting technically. You can not deactivate them.</p><p>- Session Cookie: PHP uses a Cookie to identify user sessions. Without this Cookie the Website is not working.</p><p>- XSRF-Token Cookie: Laravel automatically generates a CSRF \"token\" for each active user session managed by the application. This token is used to verify that the authenticated user is the one actually making the requests to the application.</p>'),('vi',1,'Trang chủ',NULL,'<div>[featured-posts limit=\"5\" enable_lazy_loading=\"yes\"][/featured-posts]</div><div>[simple-slider key=\"home-slider\" enable_lazy_loading=\"yes\"][/simple-slider]</div><div>[category-posts enable_lazy_loading=\"yes\"][/category-posts]</div><div>[all-galleries enable_lazy_loading=\"yes\"][/all-galleries]</div>'),('vi',2,'Giới thiệu',NULL,'<p>Chào mừng bạn đến với nền tảng của chúng tôi, nơi chúng tôi mang đến cho bạn những tin tức, hiểu biết và câu chuyện mới nhất từ khắp nơi trên thế giới. Sứ mệnh của chúng tôi là cung cấp nội dung chất lượng cao giúp thông tin, truyền cảm hứng và thu hút độc giả. Chúng tôi cam kết với sự xuất sắc và chính trực trong báo chí.</p><p>Được thành lập bởi đội ngũ nhà báo và người sáng tạo nội dung giàu kinh nghiệm, chúng tôi đã xây dựng danh tiếng trong việc cung cấp các bài viết chính xác, cân bằng và sâu sắc trên nhiều chủ đề bao gồm công nghệ, kinh doanh, phong cách sống, văn hóa và nhiều hơn nữa.</p><p>Đội ngũ biên tập của chúng tôi làm việc không ngừng để đảm bảo mỗi nội dung đều đáp ứng tiêu chuẩn cao của chúng tôi. Chúng tôi tin vào sức mạnh của việc kể chuyện để tạo nên sự khác biệt trong cuộc sống con người và giúp họ hiểu rõ hơn về thế giới xung quanh.</p><p>Cảm ơn bạn đã là một phần của cộng đồng chúng tôi. Chúng tôi mong muốn tiếp tục phục vụ bạn với nội dung tốt nhất có thể.</p>'),('vi',3,'Về chúng tôi',NULL,'<p>Chúng tôi là công ty truyền thông số hàng đầu, tận tâm cung cấp nội dung xuất sắc cho độc giả trên toàn thế giới. Với đội ngũ nhà văn, biên tập viên và người sáng tạo nội dung tài năng, chúng tôi đưa tin về những câu chuyện quan trọng nhất với bạn.</p><p>Nền tảng của chúng tôi có phân tích chuyên sâu, tin tức nóng hổi, ý kiến chuyên gia và nội dung đa phương tiện hấp dẫn. Chúng tôi tự hào về cam kết với sự chính xác, công bằng và minh bạch trong báo cáo.</p><p>Điều khiến chúng tôi khác biệt là tập trung vào chất lượng thay vì số lượng. Mỗi bài viết được nghiên cứu kỹ lưỡng, kiểm tra thực tế và biên tập để đảm bảo cung cấp thông tin đáng tin cậy nhất cho khán giả. Chúng tôi tin rằng độc giả được thông tin sẽ đưa ra quyết định tốt hơn, và chúng tôi nỗ lực trở thành nguồn thông tin đáng tin cậy của bạn.</p><p>Hãy cùng chúng tôi trên hành trình phát triển và đổi mới. Chúng tôi luôn tìm cách cải thiện và phục vụ cộng đồng tốt hơn. Phản hồi và sự ủng hộ của bạn là động lực giúp chúng tôi tốt hơn mỗi ngày.</p>'),('vi',4,'Liên hệ',NULL,'<p>123 Đường Chính, Quận Trung Tâm, Thành phố Metro, ST 12345</p><p>+1 (555) 123-4567 (4 đường dây) - +1 (555) 987-6543</p><p>+1 (555) 246-8135</p><p>contact@example.com&nbsp;&nbsp;</p><div>[contact-form][/contact-form]</div>'),('vi',5,'Cookie Policy',NULL,'<h3>EU Cookie Consent</h3><p>To use this website we are using Cookies and collecting some Data. To be compliant with the EU GDPR we give you to choose if you allow us to use certain Cookies and to collect some Data.</p><h4>Essential Data</h4><p>The Essential Data is needed to run the Site you are visiting technically. You can not deactivate them.</p><p>- Session Cookie: PHP uses a Cookie to identify user sessions. Without this Cookie the Website is not working.</p><p>- XSRF-Token Cookie: Laravel automatically generates a CSRF \"token\" for each active user session managed by the application. This token is used to verify that the authenticated user is the one actually making the requests to the application.</p>');
