INSERT INTO `posts_translations` VALUES ('ar',40,'وُجد في الترجمة: ناشر محلي يُحيي قصة رياضي أولمبي صومالي ولاجئ للقراء المقدونيين','نُشرت الرواية المصورة \"حلم أولمبي\" -- وهي سيرة ذاتية لعدّاء لقي حتفه أثناء محاولته عبور البحر الأبيض المتوسط كلاجئ -- في مقدونيا',NULL),('ar',41,'في مصر، يستمر التحرش الجنسي وزواج الأطفال في ابتلاء البلاد','\"التحرش الجنسي مشكلة كبرى في مصر. تُظهر الدراسات أن الغالبية العظمى من النساء تعرضن له [...] والمشكلة متجذرة بعمق.\"',NULL),('ar',42,'تويتر اليابان ليس مساحة آمنة لمستخدمي الأقليات','\"من بين المستجيبين الذين أفادوا بأنهم وجدوا الأمر مزعجاً عند مصادفة مقالات تمييزية على الإنترنت (كما هو موصوف أعلاه)، قال 19.8% إنهم سيمتنعون عن استخدام الإنترنت.\"',NULL),('ar',43,'مشرّع في تايوان يخاطر بسحب الثقة منه لدعمه زواج المثليين','يقوم بعض أعضاء الكنيسة المشيخية في تايوان بحملة لسحب الثقة من مشرّع بسبب دعمه لزواج المثليين، مما أثار جدلاً محتدماً ودعوات للإصلاح.',NULL),('ar',44,'مخاوف بشأن أحدث السياسات الخارجية المثيرة للجدل للرئيس الأمريكي ترامب تلوح في الأفق في أفريقيا','\"هذه ليست استراتيجية دبلوماسية. لكنها تأتي من رجل محدود الرؤية والسياسة بسبب قلة وعيه بالعالم الخارجي.\"',NULL),('ar',45,'اليونسكو تحمي عادة يوم جدة مارس البلقانية كتراث ثقافي','يحتفل ناشطو التراث الثقافي في جنوب شرق أوروبا باعتراف اليونسكو بعادة يوم جدة مارس البلقانية المتمثلة في ارتداء زينة الصوف الأحمر والأبيض.',NULL),('ar',46,'عريضة لتحرير الرجل الإريتري المعتقل ظلماً في إيطاليا بسبب خطأ في تحديد الهوية','يبدو أن السلطات الإيطالية اعتقلت الشخص الخطأ؛ هل ستعترف بذلك؟ مطاردة العقل المدبر لتهريب البشر عبر المتوسط تأخذ منعطفاً غريباً.',NULL),('ar',47,'لا يزال اللاجئون في لبنان يُستخدمون ككبش فداء في الإعلام والأوساط الأكاديمية','\"كيف يمكن الادعاء بأن هؤلاء الناس هنا لتلقي المساعدات من المنظمات الدولية، بينما كثيرون منهم في الواقع لا يتلقون أي مساعدة؟\"',NULL),('ar',49,'أهوازيو إيران يواجهون أحكام إعدام بعد اتهامات كاذبة بمعارضة الحكومة','حكمت محكمة إيرانية على رجلين عربيين أهوازيين بالإعدام ومنحت ستة آخرين أحكاماً من ثلاث إلى خمس وعشرين سنة بتهمة الانتماء المزعوم لجماعات معارضة غير موجودة.',NULL),('ar',51,'طلبات الحق في المعلومات في سريلانكا تكشف عملية حجب المواقع الإلكترونية','كشفت معلومات صادرة عن هيئة تنظيم الاتصالات أنه منذ عام 2015 تم حجب 13 موقعاً إلكترونياً، بما في ذلك عدد من المواقع التي تنشر أخباراً سياسية وبعض المواقع الإباحية.',NULL),('ar',52,'القط في... القدر؟ قطط لطيفة تغفو في أواني الطبخ اليابانية','القطط النائمة في أواني الطبخ الفخارية هي الموضة الرائجة في اليابان الآن. يبدو أنها شائعة جداً لدرجة أن المتاجر بدأت ببيع أوانٍ مصنوعة خصيصاً للقطط.',NULL),('ar',53,'الرئيس الإندونيسي جوكوي يقود المواطنين في إدانة إعلان دونالد ترامب بشأن القدس','\"ترامب يجر الولايات المتحدة والعالم إلى خط المواجهة مع التطرف الديني.\"',NULL),('ar',54,'مقال صحيفة محلية بصفحة كاملة عن النجاة من الإشعاع النووي يثير الذعر في الصين','\"يُعتقد أن المقال الكامل عن الوقاية من الإشعاع النووي هو رد فعل على خطر الحرب في شبه الجزيرة الكورية.\"',NULL),('ar',55,'سقوط قيصر الإنترنت الصيني لو وي','إذا كانت إجراءات الرقابة التي اتخذها لو وي تُعتبر انتقائية، فسيجد مستخدمو الإنترنت الصينيون أنفسهم الآن أمام نظام رقابة \"شامل\" أكثر على المحتوى الإلكتروني.',NULL),('ar',56,'سوري ولبناني: عن صراع الهويات','\"أن تكون نصف لبناني ونصف سوري يشبه أن تكون طفلاً والداه منفصلان وكلاهما يكرهك لأن كل نصف منك يذكرهما بالآخر....\"',NULL),('ar',57,'مقتل امرأة متحولة جنسياً في ترينيداد وتوباغو يسلط الضوء على النبذ الذي يواجهه مجتمع الميم','\"هذا الإنسان الرائع، الذي كان يهتم كثيراً بالآخرين، مات بلا سبب.. سوى ربما كونه مختلفاً.\"',NULL),('ar',58,'فيكتوريا تصبح أول ولاية أسترالية تقرّ قانون الموت الرحيم الطوعي','مع أن فيكتوريا أصبحت أول ولاية أسترالية تشرّع القتل الرحيم، تبقى البلاد منقسمة حول ما يُوصف بأنه توجه تقدمي جديد في السياسة الأسترالية.',NULL),('ar',59,'فيكتوريا تصبح أول ولاية أسترالية تقرّ قانون الموت الرحيم الطوعي','مع أن فيكتوريا أصبحت أول ولاية أسترالية تشرّع القتل الرحيم، تبقى البلاد منقسمة حول ما يُوصف بأنه توجه تقدمي جديد في السياسة الأسترالية.',NULL),('ar',61,'رسم قصة جديدة: فن سوهراي في جهارخاند','\"ما يميز هذا الفن هو أنه يصنعه النساء فقط وتتوارثه النساء.\"',NULL),('ar',62,'إدانة نجم دانسهول آخر لا تصدم الجامايكيين المنهكين من الجريمة','بعد سجن فايبز كارتل، يُعد نينجا مان ثاني فنان دانسهول كبير في الآونة الأخيرة يُدان بجريمة قتل في جامايكا المنهكة من الجريمة.',NULL),('ar',63,'أحكام سجن قاسية لصحفي فيديو ومدوّن مع تضييق فيتنام على حرية التعبير','\"قمع الصحفيين المواطنين ليس فقط انتهاكاً لحقوق الإنسان بل أيضاً عائق رئيسي أمام طموحات فيتنام لتصبح مركزاً للتكنولوجيا والابتكار.\"',NULL),('ar',65,'المدافع البحريني عن حقوق الإنسان المسجون نبيل رجب يواجه خمسة عشر عاماً إضافية في السجن','رجب في السجن بسبب أنشطته المتعلقة بحقوق الإنسان وبسبب التعبير الحر عن آرائه.',NULL),('ar',68,'مؤلفة قيرغيزية لكتب الأطفال تعيد صياغة الحكايات القديمة وتقود سرديات جديدة','\"لا توجد حفلات زفاف خيالية في قصصي ولا أمير وسيم. ولا تنتظره أي من شخصياتي أيضاً.\"',NULL),('ar',69,'جثث حيوانات وإطارات ونفايات طبية: تقرير جديد يسلط الضوء على المخاطر الصحية لأزمة النفايات في لبنان','\"عندما يحرقونها لا نستطيع التنفس [...] اضطررنا للذهاب إلى المستشفى بسبب هذا.\"',NULL),('ar',70,'محاولة هيئة الطاقة الذرية الروسية صنع الميمات تفشل في إخماد شائعات التسربات النووية','\"لا أحد يلوم الروثينيوم أو حتى الروثينيوم-106. إنهم يلومون روساتوم على المعلومات المتناقضة وعلى نكات كهذه بدلاً من تحقيق جدي في الحادث.\"',NULL),('ar',71,'في الصين، يُحجب التشكيك في تحقيق الشرطة حول إساءة معاملة أطفال رياض الأطفال','\"في غضون دقائق قليلة، ظهرت آلاف الأسئلة... ثم في غضون ثوانٍ قليلة، اختفت جميع التعليقات وأُغلقت خاصية التعليق.\"',NULL),('ar',72,'الروس غير معجبين بشعار الانتخابات الرئاسية 2018 (ولديهم أفكار للتحسين)','حتى الآن، كان تحدي الشعار الجزء الأكثر إثارة في الحملة حيث يُتوقع أن يترشح بوتين ويفوز حتى من قبل أشد معارضيه.',NULL),('ar',73,'نسج أشياء الفقدان والذاكرة مع هيف كهرمان','عمل كهرمان الجديد هو استكشاف بارع لقضايا الهوية والصراع الشخصي والوعي الإنساني.',NULL),('ar',74,'هذا الطبيب البرازيلي يقول إن العلم تطور لكن وصمة العار المرتبطة بفيروس نقص المناعة البشرية لا تزال قائمة','\"أصوات المتعايشين مع فيروس نقص المناعة البشرية يتجاهلها الإعلام الذي غالباً ما يصورهم كضحايا أو نماذج لا يُحتذى بها بحجة تعزيز الوقاية.\"',NULL),('ar',75,'التدقيق والشك في شهادة ضحية اغتصاب يثيران غضباً في إسبانيا','\"لا يكتفي الرجال باغتصابنا، بل عليهم أيضاً أن يخبرونا كيف نتصرف قبل وأثناء وبعد الاغتصاب.\"',NULL),('ar',77,'وُجد في الترجمة: ناشر محلي يُحيي قصة رياضي أولمبي صومالي ولاجئ للقراء المقدونيين','نُشرت الرواية المصورة \"حلم أولمبي\" -- وهي سيرة ذاتية لعدّاء لقي حتفه أثناء محاولته عبور البحر الأبيض المتوسط كلاجئ -- في مقدونيا',NULL),('ar',78,'في مصر، يستمر التحرش الجنسي وزواج الأطفال في ابتلاء البلاد','\"التحرش الجنسي مشكلة كبرى في مصر. تُظهر الدراسات أن الغالبية العظمى من النساء تعرضن له [...] والمشكلة متجذرة بعمق.\"',NULL),('ar',81,'نفاق تطبيق حقوق الإنسان للشرطة الوطنية الفلبينية','\"تطبيق \'اعرف حقوقك\' هو مثال مثالي على النفاق لأن التطبيق الوحيد المعروف لدى الشرطة الوطنية الفلبينية هو تطبيق التعذيب...\"',NULL),('ar',82,'مبادرات النشاط البيئي تنطلق في كوبا','مركز التعليم والترويج للتنمية المستدامة هو التزام بالإدارة البيئية التشاركية والبيئة السياسية في كوبا.',NULL),('fr',40,'Trouvé dans la traduction : un éditeur local donne vie à l\'histoire d\'un olympien somalien et réfugié pour les lecteurs macédoniens','Le roman graphique « Un rêve olympique » -- biographie d\'un coureur qui a péri en tentant de traverser la mer Méditerranée en tant que réfugié -- a été publié en Macédoine',NULL),('fr',41,'En Égypte, le harcèlement sexuel et les mariages d\'enfants continuent de ravager le pays','« Le harcèlement sexuel est un problème majeur en Égypte. Des études montrent que la grande majorité des femmes y ont été soumises [...] Et le problème est profondément enraciné. »',NULL),('fr',42,'Twitter Japon n\'est pas un espace sûr pour les utilisateurs issus de minorités','« Parmi les personnes interrogées qui ont déclaré avoir trouvé désagréable de tomber sur des articles discriminatoires en ligne (comme décrit ci-dessus), 19,8 % ont dit qu\'elles s\'abstiendraient d\'utiliser Internet. »',NULL),('fr',43,'Un législateur à Taïwan risque la révocation pour avoir soutenu le mariage homosexuel','Certains membres de l\'Église presbytérienne de Taïwan font campagne pour révoquer un législateur parce qu\'il soutient le mariage homosexuel, générant un débat furieux et des appels à la réforme.',NULL),('fr',44,'Les préoccupations concernant les dernières politiques étrangères controversées du président américain Trump planent sur l\'Afrique','« Ce n\'est pas une stratégie très diplomatique. Cela dit, elle vient d\'un homme dont la vision et la politique sont limitées par son manque de connaissance du monde extérieur. »',NULL),('fr',45,'L\'UNESCO protège la coutume balkanique du Jour de Grand-mère Mars en tant que patrimoine culturel','Les militants du patrimoine culturel en Europe du Sud-Est célèbrent la reconnaissance par l\'UNESCO de la coutume balkanique du Jour de Grand-mère Mars consistant à porter des ornements en laine rouge et blanche.',NULL),('fr',46,'Pétition pour libérer l\'homme érythréen injustement arrêté en Italie pour erreur d\'identité','Les autorités italiennes semblent avoir arrêté la mauvaise personne ; le reconnaîtront-elles ? La chasse au cerveau du trafic humain en Méditerranée prend une tournure étrange.',NULL),('fr',47,'Les réfugiés au Liban continuent d\'être utilisés comme boucs émissaires dans les médias et le monde académique','« Comment peut-on prétendre que ces personnes sont là pour recevoir l\'aide d\'organisations internationales, alors que beaucoup, en fait, n\'en reçoivent aucune ? »',NULL),('fr',49,'Les Ahwazis d\'Iran font face à des condamnations à mort après de fausses accusations d\'opposition au gouvernement','Un tribunal iranien a condamné deux hommes arabes ahwazis à mort et infligé à six autres des peines de trois à 25 ans pour appartenance présumée à des groupes d\'opposition inexistants.',NULL),('fr',51,'Les demandes de droit à l\'information au Sri Lanka révèlent le processus de blocage des sites web','Les informations publiées par la Commission de régulation des télécommunications ont révélé qu\'à partir de 2015, 13 sites web avaient été bloqués, dont plusieurs sites d\'actualité politique et quelques sites pornographiques.',NULL),('fr',52,'Le chat dans la... marmite ? Des félins câlins font la sieste dans des ustensiles de cuisine japonais','Les chats dormant dans des marmites en terre cuite font fureur au Japon en ce moment. Apparemment, ils sont si populaires que les magasins ont commencé à vendre des marmites conçues exclusivement pour les chats.',NULL),('fr',53,'Le président indonésien Jokowi mène les citoyens dans la condamnation de la déclaration de Donald Trump sur Jérusalem','« Trump entraîne les États-Unis et le monde en première ligne de l\'extrémisme religieux. »',NULL),('fr',54,'Un article pleine page d\'un journal local sur la survie aux radiations nucléaires suscite la panique en Chine','« L\'article pleine page sur les précautions contre les radiations nucléaires serait une réaction au risque de guerre dans la péninsule coréenne. »',NULL),('fr',55,'La chute du tsar chinois de l\'Internet Lu Wei','Si les mesures de censure de Lu Wei étaient considérées comme sélectives, les internautes chinois se retrouveront désormais face à un système de contrôle de contenu en ligne plus « complet ».',NULL),('fr',56,'Syrien et Libanais : sur le conflit des identités','« Être à moitié libanais, à moitié syrien, c\'est comme être un enfant dont les parents sont séparés et qui vous détestent tous les deux parce que chaque moitié de vous leur rappelle l\'autre... »',NULL),('fr',57,'Le meurtre d\'une femme transgenre à Trinité-et-Tobago met en lumière l\'ostracisme subi par la communauté LGBTQ','« Cet être humain merveilleux, qui se souciait tant des autres, est mort sans raison... si ce n\'est, peut-être, celle d\'être différent. »',NULL),('fr',58,'Victoria devient le premier État australien à adopter une législation sur l\'aide volontaire à mourir','Alors que Victoria devient le premier État australien à légaliser l\'euthanasie, le pays reste divisé sur ce qui est qualifié de nouvelle tendance progressiste de la politique australienne.',NULL),('fr',59,'Victoria devient le premier État australien à adopter une législation sur l\'aide volontaire à mourir','Alors que Victoria devient le premier État australien à légaliser l\'euthanasie, le pays reste divisé sur ce qui est qualifié de nouvelle tendance progressiste de la politique australienne.',NULL),('fr',61,'Peindre une nouvelle histoire : l\'art Sohrai au Jharkhand','« Ce qui rend cette forme d\'art spéciale, c\'est qu\'elle est uniquement réalisée par des femmes et transmise par des femmes. »',NULL),('fr',62,'La condamnation d\'une autre star du dancehall ne choque pas les Jamaïcains lassés par la criminalité','Après l\'incarcération de Vybz Kartel, Ninja Man est le deuxième artiste majeur du dancehall ces derniers temps à être reconnu coupable de meurtre dans une Jamaïque lassée par la criminalité.',NULL),('fr',63,'De lourdes peines de prison pour un vidéojournaliste et un blogueur alors que le Vietnam réprime la liberté d\'expression','« Réprimer les journalistes citoyens n\'est pas seulement une violation des droits de l\'homme, mais aussi un obstacle majeur aux aspirations du Vietnam à devenir un pôle technologique et d\'innovation. »',NULL),('fr',65,'Le défenseur des droits bahreïni emprisonné Nabeel Rajab risque quinze années de prison supplémentaires','Rajab est en prison pour ses activités liées aux droits de l\'homme et pour avoir librement exprimé ses opinions.',NULL),('fr',68,'Une auteure kirghize pour enfants réinvente d\'anciennes fables et crée de nouveaux récits','« Il n\'y a pas de mariages de contes de fées dans mes histoires et pas de prince charmant. Aucun de mes personnages ne l\'attend particulièrement non plus. »',NULL),('fr',69,'Carcasses d\'animaux, pneus et déchets médicaux : un nouveau rapport met en lumière les risques sanitaires de la crise des déchets au Liban','« Quand ils brûlent, on ne peut plus respirer [...] Nous avons dû aller à l\'hôpital à cause de cela. »',NULL),('fr',70,'L\'incursion du régulateur atomique russe dans la création de mèmes ne parvient pas à éteindre les rumeurs de fuites nucléaires','« Personne ne blâme le ruthénium, ni même le ruthénium-106. On blâme Rosatom pour ses informations contradictoires et pour des plaisanteries comme celle-ci au lieu d\'une enquête sérieuse sur l\'accident. »',NULL),('fr',71,'En Chine, le scepticisme autour de l\'enquête policière sur la maltraitance d\'enfants en maternelle est censuré','« En quelques minutes, des milliers de questions sont apparues... Puis en quelques secondes, tous les commentaires ont disparu et la fonction de commentaire a été fermée. »',NULL),('fr',72,'Les Russes ne sont pas impressionnés par le logo de l\'élection présidentielle de 2018 (et ont des idées pour l\'améliorer)','Jusqu\'à présent, le défi du logo a été la partie la plus passionnante de la campagne où Poutine devrait se présenter et gagner, même selon ses opposants les plus virulents.',NULL),('fr',73,'Tisser des objets de perte et de mémoire avec Hayv Kahraman','La nouvelle œuvre de Kahraman est une exploration magistrale des questions d\'identité, de lutte personnelle et de conscience humaine.',NULL),('fr',74,'Ce médecin brésilien affirme que la science a évolué, mais la stigmatisation du VIH persiste','« Les voix des personnes vivant avec le VIH sont négligées par les médias, qui les présentent souvent comme des victimes ou des exemples à ne pas suivre, sous couvert de promotion de la prévention. »',NULL),('fr',75,'L\'examen minutieux et le doute sur le témoignage d\'une victime de viol suscitent l\'indignation en Espagne','« Non contents de nous violer, les hommes doivent aussi nous dire comment nous comporter avant, pendant et après le viol. »',NULL),('fr',77,'Trouvé dans la traduction : un éditeur local donne vie à l\'histoire d\'un olympien somalien et réfugié pour les lecteurs macédoniens','Le roman graphique « Un rêve olympique » -- biographie d\'un coureur qui a péri en tentant de traverser la mer Méditerranée en tant que réfugié -- a été publié en Macédoine',NULL),('fr',78,'En Égypte, le harcèlement sexuel et les mariages d\'enfants continuent de ravager le pays','« Le harcèlement sexuel est un problème majeur en Égypte. Des études montrent que la grande majorité des femmes y ont été soumises [...] Et le problème est profondément enraciné. »',NULL),('fr',81,'L\'hypocrisie de l\'application mobile des droits de l\'homme de la Police nationale des Philippines','« L\'application « Connaissez vos droits » est un parfait exemple d\'hypocrisie car la seule application connue de la PNP est l\'application de la torture... »',NULL),('fr',82,'Les initiatives d\'activisme environnemental prennent leur essor à Cuba','Le Centre d\'éducation et de promotion pour le développement durable est un engagement en faveur de la gestion environnementale participative et de l\'écologie politique à Cuba.',NULL),('id',40,'Ditemukan dalam Terjemahan: Penerbit Lokal Menghidupkan Kisah Atlet Olimpiade dan Pengungsi Somalia untuk Pembaca Makedonia','Novel grafis \"An Olympic Dream\" -- biografi seorang pelari yang meninggal saat mencoba menyeberangi Laut Mediterania sebagai pengungsi -- diterbitkan di Makedonia',NULL),('id',41,'Di Mesir, Pelecehan Seksual dan Pernikahan Anak Terus Melanda Negara','\"Pelecehan seksual adalah masalah besar di Mesir. Studi menunjukkan bahwa sebagian besar perempuan pernah mengalaminya [...] Dan masalah ini sudah mengakar dalam.\"',NULL),('id',42,'Twitter Jepang Bukan Ruang Aman bagi Pengguna Minoritas','\"Dari responden yang melaporkan merasa tidak nyaman saat menemukan artikel diskriminatif secara daring (seperti dijelaskan di atas), 19,8% mengatakan mereka akan menahan diri dari menggunakan Internet.\"',NULL),('id',43,'Seorang Legislator di Taiwan Terancam Pemecatan karena Mendukung Pernikahan Sesama Jenis','Beberapa anggota Gereja Presbiterian di Taiwan berkampanye untuk memecat seorang legislator k